mapper.update:
UPDATE TB_LAYOUT_ITEM
   SET ITEM_NM   = #{r.itemNm,jdbcType=VARCHAR}
     , ITEM_TYPE = #{r.itemType}
     , POS_X     = COALESCE(ROUND(CAST(#{r.posX,jdbcType=VARCHAR} AS NUMERIC)), 0)
     , POS_Y     = COALESCE(ROUND(CAST(#{r.posY,jdbcType=VARCHAR} AS NUMERIC)), 0)
     , WIDTH     = ROUND(CAST(#{r.width,jdbcType=VARCHAR} AS NUMERIC))
     , HEIGHT    = ROUND(CAST(#{r.height,jdbcType=VARCHAR} AS NUMERIC))
     , ROTATE    = COALESCE(CAST(#{r.rotate,jdbcType=VARCHAR} AS INTEGER), 0)
     , SHAPE     = COALESCE(#{r.shape,jdbcType=VARCHAR}, 'rect')
     , USER_ID   = #{r.userId,jdbcType=VARCHAR}
     , MOD_ID    = #{loginId}
     , MOD_DT    = CURRENT_TIMESTAMP
 WHERE MAP_ID  = #{r.mapId}
   AND ITEM_ID = #{r.itemId}
